insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_100_v1'
from (values
('127.757.d.1.A',3,'A rural county has volunteer crews, a private ambulance service and a hospital-based transport unit. A student describing these is explaining:','["the EMS systems available to patients", "police patrol zones", "school bus routes", "fire hydrant spacing"]'::jsonb,0,'EMS systems include public, private, volunteer and hospital-based services.','original'),
('127.757.d.1.A',4,'An EMS system is best described as a network that:','["only dispatches police", "provides emergency medical care and transport for patients", "only repairs ambulances", "only teaches CPR classes"]'::jsonb,1,'EMS is a coordinated care system.','original'),
('127.757.d.1.B',3,'A paramedic starts an IV and gives cardiac drugs, while the EMT-Basic assists with oxygen and splinting. This illustrates differences in:','["shift lengths", "ambulance brands", "scope of practice among EMS provider levels", "uniform colors"]'::jsonb,2,'Scope of practice defines what each level may do.','original'),
('127.757.d.1.B',4,'An EMT-Basic should perform only skills that are:','["learned from videos", "requested by bystanders", "performed by paramedics anywhere", "within their scope of practice and local protocols"]'::jsonb,3,'Scope is set by law and medical direction.','original'),
('127.757.d.1.C',3,'Before a shift, an EMT-Basic checks that gloves, eye protection and a clean uniform are ready and gets enough sleep. This reflects responsibilities related to:','["personal safety, health and professional readiness", "radio brands", "billing rules", "vehicle paint"]'::jsonb,0,'EMTs protect themselves to protect patients.','original'),
('127.757.d.1.C',4,'Which habit supports an EMT-Basic''s personal health and wellness?','["skipping vaccinations", "maintaining physical fitness and current immunizations", "working without breaks", "ignoring injuries"]'::jsonb,1,'Fitness and immunizations reduce risk.','original'),
('127.757.d.1.D',3,'A student reads the Texas rules that decide who may be certified and what an EMT may do. This summarizes:','["parking ordinances", "sports bylaws", "state statutes and regulations governing EMS systems", "school dress codes"]'::jsonb,2,'State law governs EMS licensing and practice.','original'),
('127.757.d.1.D',4,'In Texas, EMS personnel are certified and regulated primarily by the:','["Texas Lottery Commission", "Parks and Wildlife", "Texas Education Agency", "Department of State Health Services"]'::jsonb,3,'DSHS oversees EMS certification.','original'),
('127.757.d.1.E',3,'A town compares 911 calls, text-to-911 and direct station walk-ins as ways to reach help. This researches:','["methods of accessing an EMS system", "methods of paying taxes", "methods of voting", "methods of filing reports"]'::jsonb,0,'Access methods include 911 and enhanced 911.','original'),
('127.757.d.1.E',4,'Enhanced 911 helps dispatchers because it can:','["send flowers", "show the caller''s location automatically", "block calls", "charge callers"]'::jsonb,1,'E911 displays location data.','original'),
('127.757.d.2.A',3,'A nursing home patient hands the crew a signed form saying not to attempt resuscitation. This is a:','["billing receipt", "menu order", "do not resuscitate (DNR) directive", "vaccine record"]'::jsonb,2,'A DNR directs no CPR in arrest.','original'),
('127.757.d.2.A',4,'An out-of-hospital DNR order is meant to:','["order extra tests", "transfer ownership of property", "cancel insurance", "state the patient''s wishes about resuscitation outside a hospital"]'::jsonb,3,'It documents resuscitation wishes.','original'),
('127.757.d.2.B',3,'An unconscious man is bleeding badly and no relative is present, so the crew treats him. A conscious woman says ''yes, please help me.'' These show:','["implied consent and expressed consent", "forced consent and bribes", "only written consent", "no consent and refusal"]'::jsonb,0,'Implied consent covers unresponsive patients; expressed is stated.','original'),
('127.757.d.2.B',4,'Consent a patient gives by speaking or nodding is called:','["assumed refusal", "expressed consent", "implied consent", "forced consent"]'::jsonb,1,'Expressed = actively given.','original'),
('127.757.d.2.C',3,'An EMT introduces themself, explains what will be done in simple words and asks permission before touching the patient. This models:','["avoiding the patient", "reading a manual aloud", "appropriate methods for obtaining consent", "skipping explanation"]'::jsonb,2,'Explain, then ask.','original'),
('127.757.d.2.C',4,'Before treating a conscious adult, the EMT should first:','["call a lawyer", "restrain them", "begin without speaking", "explain the care and ask permission"]'::jsonb,3,'Informed consent starts with explanation.','original'),
('127.757.d.2.D',3,'An ambulance is dispatched, arrives and begins care on a patient who needs help. This is part of conditions that create:','["a legal duty to act", "a refund", "a vacation", "an exemption"]'::jsonb,0,'Duty arises when the crew is dispatched and responds.','original'),
('127.757.d.2.D',4,'An EMT-Basic on duty has a duty to act once:','["a bystander gives an order", "dispatched and in contact with a patient needing care", "a friend asks for a favor", "the shift ends"]'::jsonb,1,'Duty begins at dispatch and patient contact.','original'),
('127.757.d.2.E',3,'A crew keeps a patient''s diagnosis private except to the receiving hospital. This shows the importance of:','["social media posting", "advertising", "patient confidentiality and its legal protections", "gossip"]'::jsonb,2,'Privacy laws like HIPAA protect patient data.','original'),
('127.757.d.2.E',4,'A law that protects the privacy of patient health information is:','["ADA", "OSHA", "FERPA", "HIPAA"]'::jsonb,3,'HIPAA covers health privacy.','original'),
('127.757.d.2.F',3,'At a possible assault scene, a crew treats the victim but avoids touching unrelated items and writes down what they moved. This is how to:','["preserve a crime scene", "destroy evidence", "clean a crime scene", "ignore a scene"]'::jsonb,0,'Limit disturbance and document changes.','original'),
('127.757.d.2.F',4,'At a crime scene, an EMT-Basic should avoid:','["noting what was changed", "moving or touching items not needed for patient care", "calling for police", "staying aware of hazards"]'::jsonb,1,'Protect evidence.','original'),
('127.757.d.2.G',3,'A crew arrives to a stabbing and a child showing signs of abuse. These situations require the EMT-Basic to:','["post online", "wait a week", "notify local law enforcement", "hide the report"]'::jsonb,2,'Violence and abuse are reportable.','original'),
('127.757.d.2.G',4,'Which situation requires an EMT to notify law enforcement?','["a missed meal", "a sprained ankle at a ballgame", "a mild headache", "suspected child abuse"]'::jsonb,3,'Abuse is mandatory to report.','original'),
('127.757.d.3.A',3,'A report says a wound is lateral to the knee and an injury is distal to the elbow. These are:','["anatomical terms of direction", "music terms", "sports terms", "cooking terms"]'::jsonb,0,'Direction terms describe location.','original'),
('127.757.d.3.A',4,'The term proximal describes a location that is:','["on the back", "closer to the point of attachment or trunk", "toward the side", "farther from the trunk"]'::jsonb,1,'Proximal means nearer the trunk.','original'),
('127.757.d.3.B',3,'A student maps how air enters the lungs, how the heart pumps blood and how the brain controls movement. This describes basic:','["tax law", "art history", "anatomy and physiology of major body systems", "car repair"]'::jsonb,2,'A&P underpins patient care.','original'),
('127.757.d.3.B',4,'The primary job of the respiratory system is to:','["filter urine", "make bone", "digest food", "move oxygen in and carbon dioxide out of the blood"]'::jsonb,3,'Gas exchange occurs in the lungs.','original'),
('127.757.d.4.A',3,'A patient breathes 16 times a minute with equal chest rise and pink skin; another gasps with blue lips. These compare signs of:','["adequate and inadequate breathing", "hunger and thirst", "hearing and sight", "strength and speed"]'::jsonb,0,'Skin color and rate show adequacy.','original'),
('127.757.d.4.A',4,'Which is a sign of inadequate breathing?','["pink skin", "cyanosis with labored effort", "regular chest rise", "normal speech"]'::jsonb,1,'Blue discoloration is inadequate.','original'),
('127.757.d.4.B',3,'A suction unit is placed within arm''s reach before opening the airway of a vomiting patient. This shows why:','["suction is optional", "suction is decorative", "suction must be ready for immediate use", "suction wastes time"]'::jsonb,2,'Fluids can block the airway quickly.','original'),
('127.757.d.4.B',4,'Having suction ready is important because airway fluids can:','["improve oxygen", "cool the patient", "relieve pain", "quickly obstruct breathing"]'::jsonb,3,'Blood and vomit block airways.','original'),
('127.757.d.4.C',3,'A trainee measures the catheter, inserts it without suction, then applies suction while withdrawing. This demonstrates:','["proper suctioning technique to clear the airway", "pushing fluid deeper", "skipping a step", "wasteful practice"]'::jsonb,0,'Suction only on withdrawal.','original'),
('127.757.d.4.C',4,'Suctioning an adult''s mouth should generally be limited to about:','["nonstop", "10 to 15 seconds at a time", "2 minutes", "5 minutes"]'::jsonb,1,'Prolonged suction causes hypoxia.','original'),
('127.757.d.4.D',3,'A trainee measures from the corner of the mouth to the earlobe to size an airway tool. This demonstrates:','["splinting a leg", "taking a pulse", "techniques and devices used to secure the airway", "logging a call"]'::jsonb,2,'Sizing an oral airway uses that landmark.','original'),
('127.757.d.4.D',4,'An oropharyngeal airway is sized by measuring from the corner of the mouth to the:','["belly button", "knee", "shoulder", "angle of the jaw or earlobe"]'::jsonb,3,'That distance fits the OPA.','original'),
('127.757.d.4.E',3,'A crew performs a head-tilt chin-lift, then a jaw-thrust when a spine injury is possible. These are:','["basic airway techniques", "imaging methods", "advanced surgery", "billing steps"]'::jsonb,0,'Basic airway maneuvers open the airway.','original'),
('127.757.d.4.E',4,'The jaw-thrust maneuver is used instead of head-tilt when:','["the patient is a pet", "a spinal injury is suspected", "the patient is awake and hungry", "the airway is already clear"]'::jsonb,1,'It avoids neck movement.','original'),
('127.757.d.4.F',3,'A crew attaches a small sensor to the breathing circuit that displays exhaled carbon dioxide. This is the use of:','["a thermometer", "a stethoscope", "end-tidal capnography (ETCO2)", "a scale"]'::jsonb,2,'ETCO2 monitors ventilation.','original'),
('127.757.d.4.F',4,'End-tidal capnography measures:','["blood sugar", "body weight", "hearing level", "carbon dioxide in exhaled breath"]'::jsonb,3,'ETCO2 reflects ventilation.','original'),
('127.757.d.4.G',3,'A monitor shows a normal rectangular waveform with a reading near 35–45 mmHg. This suggests:','["adequate ventilation", "no ventilation at all", "a dead monitor", "a broken screen"]'::jsonb,0,'Normal ETCO2 is about 35–45.','original'),
('127.757.d.4.G',4,'A flat ETCO2 waveform with a reading of zero after intubation may indicate:','["the monitor is too warm", "the tube is not in the airway or there is no breathing", "a happy patient", "perfect ventilation"]'::jsonb,1,'No CO2 means no exhaled air.','original'),
('127.757.d.4.H',3,'A trained EMT inserts an advanced device above the vocal cords to maintain an airway when bag-valve-mask ventilation is inadequate. This is a:','["feeding tube", "splint", "supraglottic airway device", "blood pressure cuff"]'::jsonb,2,'Supraglottic devices sit above the glottis.','original'),
('127.757.d.4.H',4,'An example of a supraglottic airway device is the:','["glucometer", "tourniquet", "cervical collar", "i-gel"]'::jsonb,3,'i-gel is a supraglottic airway.','original'),
('127.757.d.5.A',3,'On arrival at a highway collision, the crew first looks for traffic, fuel leaks and downed wires. This is evaluating:','["scene hazards to responders, patients and bystanders", "the radio signal", "the weather forecast only", "the ambulance''s paint"]'::jsonb,0,'Scene size-up begins with safety.','original'),
('127.757.d.5.A',4,'The first priority on arrival at an emergency scene is:','["paperwork", "scene safety", "billing", "photography"]'::jsonb,1,'Never become a second victim.','original'),
('127.757.d.5.B',3,'A crew counts the patients, notes the mechanism of injury and decides to request more units. This is:','["a training exam", "a lunch break", "scene assessment and resource determination", "a shift change"]'::jsonb,2,'Size-up decides resources.','original'),
('127.757.d.5.B',4,'After noting more patients than the crew can manage, the EMT should:','["wait silently", "treat only one", "leave the scene", "request additional resources"]'::jsonb,3,'Call for help early.','original'),
('127.757.d.5.C',3,'The EMT forms a general impression and checks responsiveness, airway, breathing and circulation first. This is the:','["initial patient assessment", "vehicle inspection", "billing audit", "equipment inventory"]'::jsonb,0,'Initial assessment finds life threats.','original'),
('127.757.d.5.C',4,'During an initial assessment, life-threatening problems are found by checking:','["birth month", "airway, breathing and circulation", "hair color", "shoe size"]'::jsonb,1,'ABCs guide priority.','original'),
('127.757.d.5.D',3,'At a bus crash with ten victims, the crew tags each patient red, yellow, green or black. This demonstrates:','["a shift roster", "a pay scale", "a triage method to determine patient priority", "a filing system"]'::jsonb,2,'Triage assigns priority.','original'),
('127.757.d.5.D',4,'In color-coded triage, red usually means the patient:','["is deceased", "can wait", "walks away", "needs immediate treatment"]'::jsonb,3,'Red = immediate.','original'),
('127.757.d.5.E',3,'A crew checks a fall victim''s head, neck, chest, abdomen, pelvis and limbs for deformities, tenderness and swelling. This is assessing:','["traumatic injuries", "sleepiness", "boredom", "hunger"]'::jsonb,0,'Rapid trauma assessment looks for DCAP-BTLS signs.','original'),
('127.757.d.5.E',4,'DCAP-BTLS is a memory aid for finding signs of:','["traffic", "trauma during a physical assessment", "billing", "weather"]'::jsonb,1,'Deformities, contusions, abrasions, punctures, burns, tenderness, lacerations, swelling.','original'),
('127.757.d.5.F',3,'The EMT asks questions about symptoms, allergies and medications, then takes vital signs. This is the components of:','["a vehicle test", "a menu review", "a focused patient assessment and history", "a repair order"]'::jsonb,2,'SAMPLE and OPQRST organize the history.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_100_v1'
from (values
('127.757.d.5.F',4,'The SAMPLE history includes questions about:','["vacation, cars and weather", "money, jobs and phones", "music, sports and fashion", "signs/symptoms, allergies, medications and past history"]'::jsonb,3,'SAMPLE structures history taking.','original'),
('127.757.d.5.G',3,'On a stable patient en route, the EMT performs a head-to-toe check without rushing. This is a:','["detailed physical examination", "paperwork", "phone call", "quick glance"]'::jsonb,0,'Detailed exam is thorough, when time permits.','original'),
('127.757.d.5.G',4,'A detailed physical exam is generally performed:','["never", "after life threats are managed and time allows", "on every patient first", "before checking responsiveness"]'::jsonb,1,'It follows the primary survey.','original'),
('127.757.d.5.H',3,'A dispatcher relays a call to the unit by radio, and the crew reports to the hospital by cell phone. These are components of:','["an alarm clock", "a menu system", "common EMS communication systems", "a billing system"]'::jsonb,2,'Radio and phone are core tools.','original'),
('127.757.d.5.H',4,'When reporting to the hospital by radio, the EMT should:','["use slang", "speak quickly and mumble", "share unrelated details", "speak clearly and give a concise, organized report"]'::jsonb,3,'Clear reports aid hospital prep.','original'),
('127.757.d.5.I',3,'After transport, an EMT records times, vital signs, treatments and patient condition on a form. This is a:','["pre-hospital patient care report", "time card for school", "recipe card", "grocery list"]'::jsonb,0,'The PCR documents care.','original'),
('127.757.d.5.I',4,'A written patient care report should be:','["opinionated", "accurate, complete and objective", "short and vague", "left blank"]'::jsonb,1,'Documentation must be factual.','original'),
('127.757.d.5.J',3,'A patient is assessed and declines transport; the EMT documents the findings, risks explained and signatures. This describes:','["a billing dispute", "a maintenance form", "a no-transport report", "an insurance claim"]'::jsonb,2,'Document refusal thoroughly.','original'),
('127.757.d.5.J',4,'A no-transport report should include:','["only the weather", "the driver''s lunch", "only the ambulance number", "assessment findings and the patient''s refusal documentation"]'::jsonb,3,'It records what happened and why.','original'),
('127.757.d.5.K',3,'A competent adult declines care after the EMT explains the risks. This analysis involves legal considerations of:','["patient refusal", "parking permits", "vehicle licensing", "a free ride"]'::jsonb,0,'Competent patients may refuse.','original'),
('127.757.d.5.K',4,'For a patient to legally refuse care, they must be:','["a minor alone", "competent and informed of the risks", "intoxicated", "unconscious"]'::jsonb,1,'Capacity and information are required.','original'),
('127.757.d.6.A',3,'A patient shows chest pressure, wheezing, sudden weakness on one side or sweaty confusion. These are:','["signs of luck", "signs of rest", "signs and symptoms of medical emergencies", "signs of fitness"]'::jsonb,2,'Recognize emergency presentations.','original'),
('127.757.d.6.A',4,'Sudden weakness on one side of the body with slurred speech suggests:','["a rash", "a sprain", "a cold", "a stroke"]'::jsonb,3,'Face droop, arm weakness, speech difficulty.','original'),
('127.757.d.6.B',3,'For each medical emergency, a protocol says to give oxygen, position the patient and monitor vitals. This describes:','["medical care for medical emergencies", "filing steps", "repair steps", "billing steps"]'::jsonb,0,'Care follows protocol.','original'),
('127.757.d.6.B',4,'A patient in respiratory distress is commonly positioned:','["standing", "sitting up in a position of comfort", "flat on their stomach", "head below the heart"]'::jsonb,1,'Upright eases breathing.','original'),
('127.757.d.6.C',3,'An EMT-Basic may help a patient take their own prescribed nitroglycerin or give oxygen, glucose or aspirin per protocol. These are:','["surgical drugs", "chemotherapy drugs", "common medications EMT-Basics may administer", "anesthetics"]'::jsonb,2,'EMT-Basic meds are limited.','original'),
('127.757.d.6.C',4,'A medication an EMT-Basic may give for suspected heart attack is:','["insulin", "morphine", "antibiotics", "aspirin"]'::jsonb,3,'Aspirin is commonly allowed.','original'),
('127.757.d.6.D',3,'A person with asthma, COPD or pneumonia struggles to breathe and wheezes. These are:','["common respiratory emergencies", "burn injuries", "bone injuries", "eye injuries"]'::jsonb,0,'They disrupt airflow or gas exchange.','original'),
('127.757.d.6.D',4,'Wheezing is typically a sign of:','["low blood sugar", "narrowed airways", "a rash", "a broken arm"]'::jsonb,1,'Airway narrowing causes wheezes.','original'),
('127.757.d.6.E',3,'The EMT sits the patient up, administers oxygen and assists with a prescribed inhaler. This is appropriate care for:','["a nosebleed", "a sprain", "respiratory distress", "a burn"]'::jsonb,2,'Oxygen and bronchodilators help.','original'),
('127.757.d.6.E',4,'An EMT may assist with a patient''s prescribed inhaler if the patient:','["is unconscious", "wants one", "is a child alone", "has a prescription and medical direction allows it"]'::jsonb,3,'Requires authorization.','original'),
('127.757.d.6.F',3,'A man with crushing chest pain radiating to the arm, and a woman with face droop, are examples of:','["cardiovascular emergencies", "vision issues", "skin conditions", "sleep problems"]'::jsonb,0,'Heart attack and stroke are cardiovascular emergencies.','original'),
('127.757.d.6.F',4,'Chest pain with sweating and nausea may indicate:','["a sunburn", "a heart attack", "a cold", "a sprain"]'::jsonb,1,'Classic acute coronary signs.','original'),
('127.757.d.6.G',3,'A trainee places electrodes on both wrists, both ankles and six chest positions. This demonstrates standard placement for a:','["thermometer", "scale", "12-lead ECG", "splint"]'::jsonb,2,'Limb and chest leads form 12 leads.','original'),
('127.757.d.6.G',4,'Proper electrode placement is important because it:','["cools the patient", "hides symptoms", "adds weight", "produces an accurate heart tracing"]'::jsonb,3,'Misplacement distorts the ECG.','original'),
('127.757.d.6.H',3,'Crews send an ECG to the emergency department from the field so the hospital can prepare. This explains the purpose of:','["transmitting a 12-lead ECG", "billing codes", "parking tickets", "dispatch logs"]'::jsonb,0,'Early notification speeds care.','original'),
('127.757.d.6.H',4,'Transmitting a 12-lead ECG from the scene helps the hospital to:','["close the unit", "prepare for a possible heart attack before arrival", "avoid treatment", "delay the patient"]'::jsonb,1,'Pre-arrival activation saves time.','original'),
('127.757.d.6.I',3,'In a simulation, a trainee assists a patient with prescribed nitroglycerin for chest pain after checking blood pressure. This simulates:','["feeding the patient", "giving antibiotics", "administration of prescribed nitroglycerin", "cleaning a wound"]'::jsonb,2,'Nitroglycerin relaxes vessels.','original'),
('127.757.d.6.I',4,'Before assisting with nitroglycerin, the EMT must confirm the patient''s:','["address", "insurance card", "favorite color", "blood pressure is adequate and the drug is prescribed to them"]'::jsonb,3,'Hypotension is a contraindication.','original'),
('127.757.d.6.J',3,'A crew attaches pads to an unresponsive pulseless patient and follows prompts. This demonstrates the use of an:','["automated external defibrillator", "splint", "suction unit", "oxygen tank"]'::jsonb,0,'AED analyzes rhythm and shocks.','original'),
('127.757.d.6.J',4,'An AED should be used on a patient who is:','["walking", "unresponsive, not breathing and without a pulse", "sleeping normally", "alert and talking"]'::jsonb,1,'AEDs treat cardiac arrest.','original'),
('127.757.d.6.K',3,'A confused diabetic patient is sweaty, shaky and irritable. This identifies signs of altered mental status associated with:','["burns", "broken bones", "low or high blood sugar", "hearing loss"]'::jsonb,2,'Diabetic emergencies alter mentation.','original'),
('127.757.d.6.K',4,'Altered mental status in a diabetic patient may be caused by:','["a haircut", "new shoes", "a vacation", "hypoglycemia"]'::jsonb,3,'Low sugar causes confusion.','original'),
('127.757.d.6.L',3,'A conscious diabetic patient with low sugar is given oral glucose after the EMT confirms they can swallow. This lists steps for care of:','["a hypoglycemic patient", "a fracture patient", "a burn patient", "a choking patient"]'::jsonb,0,'Give sugar if able to swallow.','original'),
('127.757.d.6.L',4,'Oral glucose should be given to a hypoglycemic patient only if they are:','["vomiting heavily", "awake and able to swallow", "unable to follow commands", "unconscious"]'::jsonb,1,'Aspiration risk otherwise.','original'),
('127.757.d.6.M',3,'After a bee sting, a patient develops hives, swelling of the face and difficulty breathing. These are signs of:','["a cold", "a fever", "an allergic reaction", "a sprain"]'::jsonb,2,'Anaphylaxis involves multiple systems.','original'),
('127.757.d.6.M',4,'A severe allergic reaction may cause:','["better breathing", "a rash only", "lower pulse always", "airway swelling and low blood pressure"]'::jsonb,3,'Anaphylaxis threatens airway and circulation.','original'),
('127.757.d.6.N',3,'The EMT supports the airway, gives oxygen and helps with the patient''s prescribed epinephrine auto-injector. This is care for:','["allergic reactions including anaphylaxis", "a minor scrape", "a bruise", "a headache"]'::jsonb,0,'Epinephrine reverses anaphylaxis.','original'),
('127.757.d.6.N',4,'An epinephrine auto-injector is used to treat:','["seizures", "severe allergic reactions", "broken bones", "burns"]'::jsonb,1,'It reverses anaphylaxis.','original'),
('127.757.d.6.O',3,'A toddler is found near an open cabinet of cleaners with burns around the mouth. These are signs of:','["a sprain", "a fever", "poisoning", "a cold"]'::jsonb,2,'Look for source and signs.','original'),
('127.757.d.6.O',4,'Poison can enter the body through:','["only hearing", "only bright lights", "only touch with sight", "ingestion, inhalation, absorption and injection"]'::jsonb,3,'Four routes of entry.','original'),
('127.757.d.6.P',3,'The EMT contacts Poison Control, identifies the substance and follows direction before giving any treatment. This is care for:','["suspected poisoning", "a sprain", "a fracture", "a burn"]'::jsonb,0,'Poison Control guides treatment.','original'),
('127.757.d.6.P',4,'The national Poison Help line number is:','["1-900-123-4567", "1-800-222-1222", "1-800-555-0000", "1-888-999-1111"]'::jsonb,1,'Poison Help is 1-800-222-1222.','original'),
('127.757.d.6.Q',3,'The EMT counts a pulse, counts respirations, measures blood pressure and notes skin color and temperature. These are:','["vehicle checks", "billing codes", "vital signs", "dispatch notes"]'::jsonb,2,'Vitals trend patient condition.','original'),
('127.757.d.6.Q',4,'A normal resting adult pulse is about:','["300", "10 to 20", "150 to 200", "60 to 100 beats per minute"]'::jsonb,3,'Typical adult pulse.','original'),
('127.757.d.6.R',3,'Two EMTs use proper body mechanics to lift a stretcher while keeping their backs straight and legs bent. This is:','["proper techniques for lifting and moving patients", "random lifting", "unsafe lifting", "speed lifting"]'::jsonb,0,'Protect the back; use legs.','original'),
('127.757.d.6.R',4,'When lifting, an EMT should keep the load:','["twisted", "close to the body with the back straight", "far from the body", "overhead"]'::jsonb,1,'Reduce strain.','original'),
('127.757.d.6.S',3,'A swimmer pulled from a pool is coughing, short of breath and pale. This lists signs of:','["a headache", "a sunburn", "a water-related emergency such as near-drowning", "a cold"]'::jsonb,2,'Drowning can cause respiratory distress.','original'),
('127.757.d.6.S',4,'The priority for a near-drowning patient is:','["a tan", "paperwork", "a snack", "airway and breathing"]'::jsonb,3,'Ventilation is first.','original'),
('127.757.d.6.T',3,'A patient who is severely agitated, paranoid and threatening to harm themselves presents a:','["behavioral emergency", "bruise", "sprain", "burn"]'::jsonb,0,'Behavior is a medical concern.','original'),
('127.757.d.6.T',4,'A behavioral emergency can affect patient care by:','["making care easier", "making the scene less safe and limiting cooperation", "improving cooperation", "removing hazards"]'::jsonb,1,'Behavior can increase risk.','original'),
('127.757.d.6.U',3,'Before transporting a patient with a psychiatric crisis, the EMT considers consent, capacity and whether law enforcement is needed. This identifies:','["menu choices", "vehicle colors", "medical and legal considerations in psychological emergencies", "tax rules"]'::jsonb,2,'Capacity and safety matter.','original'),
('127.757.d.6.U',4,'In a psychological emergency, an EMT should be aware of:','["only the weather", "only radio brands", "only paperwork length", "the patient''s rights and legal requirements for treatment"]'::jsonb,3,'Legal rights apply.','original'),
('127.757.d.6.V',3,'The EMT stays calm, speaks gently, keeps a safe distance and listens. This describes emergency care for a patient with:','["a behavioral problem", "a laceration", "a burn", "a fracture"]'::jsonb,0,'De-escalation supports safety.','original'),
('127.757.d.6.V',4,'A helpful approach with an agitated patient is to:','["argue", "stay calm, listen and avoid sudden movements", "crowd them", "shout"]'::jsonb,1,'De-escalate.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_100_v1'
from (values
('127.757.d.6.W',3,'If a combative patient may injure themselves or others, trained crews use approved restraint with enough personnel and documentation. This describes:','["random methods", "no plan", "safe restraint techniques", "any force"]'::jsonb,2,'Restraint must be safe and justified.','original'),
('127.757.d.6.W',4,'When restraint is used, the EMT must make sure the patient''s:','["face is covered", "voice is silent", "hands are hidden", "airway and breathing are not compromised"]'::jsonb,3,'Never restrict breathing.','original'),
('127.757.d.6.X',3,'A pregnant patient reports severe abdominal pain and vaginal bleeding. These are signs that can indicate:','["a medical problem during pregnancy", "a normal day", "a minor cold", "a haircut"]'::jsonb,0,'Bleeding and pain are warning signs.','original'),
('127.757.d.6.X',4,'Which is a warning sign in a pregnant patient?','["mild fatigue", "vaginal bleeding with severe pain", "normal movement", "slight appetite change"]'::jsonb,1,'Bleeding with pain needs urgent care.','original'),
('127.757.d.6.Y',3,'The EMT places a pregnant patient on her left side, gives oxygen and transports promptly. This identifies procedures to:','["ignore her", "delay transport", "stabilize a pregnant patient showing warning signs", "remove oxygen"]'::jsonb,2,'Left-side positioning improves circulation.','original'),
('127.757.d.6.Y',4,'Positioning a pregnant patient on her left side helps because it:','["slows breathing", "warms the body", "raises blood sugar", "keeps the uterus from pressing on major blood vessels"]'::jsonb,3,'Avoids vena cava compression.','original'),
('127.757.d.7.A',3,'A patient with a severe injury has pale, cool skin, a weak fast pulse and falling blood pressure. This describes how shock affects:','["the cardiovascular and other major body systems", "only the nails", "only the hair", "only the teeth"]'::jsonb,0,'Shock reduces perfusion across systems.','original'),
('127.757.d.7.A',4,'In shock, the body''s cells are harmed because they do not receive enough:','["sunlight", "oxygen-rich blood", "exercise", "noise"]'::jsonb,1,'Hypoperfusion starves tissue.','original'),
('127.757.d.7.B',3,'A crew applies direct pressure, then a pressure dressing, and uses a tourniquet if bleeding continues on a limb. This is care for:','["a cough", "a headache", "controlling external bleeding", "a rash"]'::jsonb,2,'Escalate from pressure to tourniquet.','original'),
('127.757.d.7.B',4,'The first step to control most external bleeding is:','["walking it off", "a drink of water", "a hot pack", "direct pressure with a dressing"]'::jsonb,3,'Direct pressure first.','original'),
('127.757.d.7.C',3,'A patient has a rigid, tender abdomen, dizziness and rapid pulse after a fall with no visible wound. These are signs of:','["internal bleeding", "a sunburn", "a cold", "indigestion only"]'::jsonb,0,'Internal bleeding may be hidden.','original'),
('127.757.d.7.C',4,'Which finding suggests internal bleeding?','["a clean scrape", "a tender, distended abdomen with signs of shock", "a mild itch", "a hiccup"]'::jsonb,1,'Distension and shock signs.','original'),
('127.757.d.7.D',3,'After a steering-wheel impact, the EMT suspects bleeding in the chest and abdomen from the crash forces. This identifies internal bleeding by:','["birth date", "shoe size", "mechanism of injury", "favorite team"]'::jsonb,2,'MOI predicts injuries.','original'),
('127.757.d.7.D',4,'A high-speed collision with a bent steering wheel should make the EMT suspect:','["only a bruise", "a minor issue", "no injury at all", "serious internal injuries"]'::jsonb,3,'Significant MOI warrants concern.','original'),
('127.757.d.7.E',3,'A cut, a bruise and a crushing injury with swelling represent open, closed and blunt types of:','["soft tissue injuries", "lung diseases", "eye diseases", "bone diseases"]'::jsonb,0,'Soft tissue injuries vary.','original'),
('127.757.d.7.E',4,'A wound in which the skin is broken is called:','["a contusion", "an open wound", "a closed wound", "a bruise"]'::jsonb,1,'Open wounds break the skin.','original'),
('127.757.d.7.F',3,'The EMT applies a cold pack, rests and elevates a swollen bruised limb. This is care for a:','["burn", "amputation", "closed soft tissue injury such as a contusion", "laceration"]'::jsonb,2,'RICE-type care limits swelling.','original'),
('127.757.d.7.F',4,'For a closed soft tissue injury, applying cold helps to:','["raise temperature", "increase bleeding", "stop breathing", "reduce swelling and pain"]'::jsonb,3,'Cold limits swelling.','original'),
('127.757.d.7.G',3,'A trainee covers a laceration with sterile gauze, then wraps a bandage snugly while checking circulation below it. This demonstrates:','["dressing wounds and applying bandages", "tying a shoe", "cooking", "gardening"]'::jsonb,0,'Dress then bandage; check pulses.','original'),
('127.757.d.7.G',4,'After applying a bandage to a limb, the EMT should check:','["the driver''s shift", "circulation, sensation and movement below it", "the radio", "the weather"]'::jsonb,1,'Avoid bandages that are too tight.','original'),
('127.757.d.7.H',3,'A student labels the femur, humerus and skull and explains how bones support and protect the body. This identifies:','["nerves of the eye", "glands", "bones and functions of the musculoskeletal system", "organs of digestion"]'::jsonb,2,'Bones support, protect and move.','original'),
('127.757.d.7.H',4,'The primary function of the skull is to:','["filter air", "pump blood", "digest food", "protect the brain"]'::jsonb,3,'Skull encloses the brain.','original'),
('127.757.d.7.I',3,'One patient has a broken bone piercing the skin; another has a broken bone with intact skin. This identifies:','["open and closed fractures", "burns and frostbite", "cuts and scrapes", "strains and sprains"]'::jsonb,0,'Open fractures break the skin.','original'),
('127.757.d.7.I',4,'In an open fracture, the major added risk compared with a closed fracture is:','["no treatment needed", "infection and bleeding", "better healing", "less pain always"]'::jsonb,1,'Skin break exposes bone.','original'),
('127.757.d.7.J',3,'The EMT pads a swollen, deformed forearm and splints it above and below the injury. This demonstrates:','["ignoring the arm", "rubbing the arm", "immobilization of a painful, swollen, deformed extremity", "stretching the arm"]'::jsonb,2,'Splint the joints above and below.','original'),
('127.757.d.7.J',4,'Before and after splinting a limb, the EMT should check:','["the patient''s hair", "the ambulance tires", "the weather report", "pulse, sensation and movement distal to the injury"]'::jsonb,3,'PMS checks protect circulation.','original'),
('127.757.d.7.K',3,'A student explains how the spinal cord carries signals from the brain through the bony vertebrae that surround it. This analyzes the relationship between the:','["skeletal and nervous systems", "respiratory and urinary systems", "lymph and skin systems", "muscular and digestive systems"]'::jsonb,0,'Vertebrae protect the cord.','original'),
('127.757.d.7.K',4,'Damage to the spine is serious mainly because it can injure the:','["fingernails", "spinal cord", "teeth", "hair"]'::jsonb,1,'Cord injury can cause paralysis.','original'),
('127.757.d.7.L',3,'A diving into a shallow pool and a high-speed rollover are examples of mechanisms that can cause:','["a sunburn", "a toothache", "cervical spine injury", "a cold"]'::jsonb,2,'Axial load and flexion injure the neck.','original'),
('127.757.d.7.L',4,'A mechanism that suggests possible neck injury is:','["a nap", "a paper cut", "a sneeze", "a fall from a height"]'::jsonb,3,'Falls can injure the cervical spine.','original'),
('127.757.d.7.M',3,'The EMT holds the head in line, applies a properly sized collar and secures the patient to a board. This applies:','["stabilization techniques for cervical spine injuries", "bending the neck", "lifting the head", "shaking the patient"]'::jsonb,0,'Manual stabilization and collar.','original'),
('127.757.d.7.M',4,'Manual in-line stabilization of the head is used to:','["drain fluids", "prevent movement of a possibly injured neck", "warm the head", "wake the patient"]'::jsonb,1,'Keep the spine aligned.','original'),
('127.757.d.8.A',3,'A toddler has a faster breathing rate and smaller airway than an adult, so the crew adjusts equipment size. This differentiates care for:','["animals", "machines", "infants, children and adults", "students only"]'::jsonb,2,'Pediatric anatomy differs.','original'),
('127.757.d.8.A',4,'Compared with adults, an infant''s airway is:','["immune to blockage", "identical", "larger", "smaller and easier to block"]'::jsonb,3,'Infants obstruct more easily.','original'),
('127.757.d.8.B',3,'A choking baby is placed face-down on the rescuer''s forearm and given back blows and chest thrusts. This demonstrates techniques for:','["foreign body airway obstruction in an infant", "bathing", "feeding", "burping"]'::jsonb,0,'Infant FBAO uses back blows and chest thrusts.','original'),
('127.757.d.8.B',4,'For a conscious choking adult, the rescuer should give:','["a glass of water", "abdominal thrusts", "a back rub", "a hug"]'::jsonb,1,'Heimlich maneuver.','original'),
('127.757.d.8.C',3,'A crew assesses a child, uses a bag-valve-mask with a child-size mask and gives oxygen. This demonstrates:','["skipping oxygen", "ignoring the child", "pediatric assessment and ventilation support", "adult-only care"]'::jsonb,2,'BVM sizing matters.','original'),
('127.757.d.8.C',4,'When using a bag-valve-mask on a child, the mask must:','["be upside down", "be as large as possible", "be loose", "fit snugly over the nose and mouth"]'::jsonb,3,'A seal is needed.','original'),
('127.757.d.8.D',3,'The EMT protects a seizing child from injury, gives oxygen and treats a respiratory emergency. This describes care for:','["pediatric emergencies such as seizures and respiratory distress", "a paper cut", "a stubbed toe", "a cold sore"]'::jsonb,0,'Protect and support breathing.','original'),
('127.757.d.8.D',4,'During a seizure, the EMT should:','["shake them", "protect the patient from injury and not restrain them", "put something in their mouth", "hold them down"]'::jsonb,1,'Do not restrain.','original'),
('127.757.d.9.A',3,'A state law says when an ambulance may exceed the speed limit and what it must do at red lights. This describes:','["pedestrian rules", "school bus rules", "state laws related to the operation of an ambulance", "bicycle rules"]'::jsonb,2,'State statutes govern emergency vehicles.','original'),
('127.757.d.9.A',4,'When operating an ambulance with lights and siren, the driver must still:','["ignore all traffic", "drive recklessly", "avoid training", "drive with due regard for the safety of others"]'::jsonb,3,'Due regard applies.','original'),
('127.757.d.9.B',3,'A trainee sorts terms: removing dirt, killing most germs, killing nearly all germs and killing all microbes. These define:','["cleaning, disinfection, high-level disinfection and sterilization", "packing steps", "painting steps", "cooking steps"]'::jsonb,0,'Levels of decontamination differ.','original'),
('127.757.d.9.B',4,'Sterilization is the process that:','["adds soap", "destroys all microbial life", "lowers temperature", "removes visible dirt only"]'::jsonb,1,'Highest level of germ kill.','original'),
('127.757.d.9.C',3,'After a call, crews wipe the stretcher with an approved disinfectant and replace used linens. This describes how to:','["ignore equipment", "skip cleaning", "clean and disinfect patient care equipment", "reuse sheets"]'::jsonb,2,'Cleaning protects patients.','original'),
('127.757.d.9.C',4,'After transporting a patient, a stretcher should be:','["left dirty", "taken apart", "painted", "cleaned and disinfected before the next patient"]'::jsonb,3,'Prevent cross-contamination.','original'),
('127.757.d.9.D',3,'For a bleeding trauma patient, the EMT wears gloves, eye protection and a gown. This identifies types and uses of:','["personal protective equipment", "game gear", "sports equipment", "dress clothes"]'::jsonb,0,'PPE protects the responder.','original'),
('127.757.d.9.D',4,'Standard precautions require which minimum PPE when contact with body fluids is possible?','["earrings", "gloves", "a sun hat", "sandals"]'::jsonb,1,'Gloves are the baseline.','original'),
('127.757.d.9.E',3,'At a crash, a rescue team uses tools to free a trapped driver without causing more injury. This explains the purpose of:','["towing for fees", "car washing", "patient extrication", "parking"]'::jsonb,2,'Extrication removes patients safely.','original'),
('127.757.d.9.E',4,'A key principle of extrication is to:','["skip planning", "avoid communication", "work as quickly as possible regardless", "protect the patient from further injury"]'::jsonb,3,'Patient safety first.','original'),
('127.757.d.9.F',3,'A rescuer opens an unlocked door; another must cut the roof with tools. This distinguishes:','["simple and complex access methods", "dry and wet", "hot and cold", "fast and slow breathing"]'::jsonb,0,'Simple = no tools; complex = tools.','original'),
('127.757.d.9.F',4,'An example of simple access to a vehicle is:','["cutting the roof", "opening an unlocked door", "breaking all windows", "using hydraulic spreaders"]'::jsonb,1,'Simple access uses no tools.','original'),
('127.757.d.9.G',3,'At a spill with unknown liquid, the EMT stays outside the hot zone and waits for hazmat teams. This describes the EMT''s role during:','["a parade", "a ball game", "a hazardous materials incident", "a picnic"]'::jsonb,2,'EMTs avoid contamination.','original'),
('127.757.d.9.G',4,'At a hazardous materials incident, an EMT-Basic should treat patients only after they are:','["still contaminated", "in the hot zone", "untouched", "decontaminated and in a safe area"]'::jsonb,3,'Decon before treatment.','original'),
('127.757.d.9.H',3,'On arrival at a scene where a crash involves many victims, the EMT notifies dispatch, sets up command and follows the plan in order. This describes the sequential steps in:','["responding to a multiple-casualty incident", "a vacation", "a routine call", "a drill only"]'::jsonb,0,'Command and communication first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
