from (values
('127.757.d.9.H',4,'One of the first actions at a large incident is to:','["go home", "establish command and request resources", "disband units", "start billing"]'::jsonb,1,'Command structure is first.','original'),
('127.757.d.9.I',3,'A response involving more patients than the first crew can handle is classified as a:','["minor call", "training day", "multiple-casualty incident", "service check"]'::jsonb,2,'MCI exceeds routine resources.','original'),
('127.757.d.9.I',4,'A multiple-casualty incident is generally defined by:','["type of ambulance", "time of day", "weather", "the number of patients overwhelming available resources"]'::jsonb,3,'Resources vs. need.','original'),
('127.757.d.9.J',3,'A tornado hits a town and the county declares a disaster, activating plans and mutual aid. This describes criteria to:','["initiate disaster operations", "end operations", "ignore events", "avoid operations"]'::jsonb,0,'Large scale triggers disaster mode.','original'),
('127.757.d.9.J',4,'A disaster operation is typically triggered when an event:','["is minor", "overwhelms normal local EMS capacity", "is planned", "is routine"]'::jsonb,1,'Capacity exceeded.','original'),
('127.757.d.9.K',3,'At a mass casualty scene, the crew sorts patients quickly using START to assign priority. This demonstrates:','["an inventory count", "a sorting game", "triage principles used during a mass casualty incident", "a billing method"]'::jsonb,2,'Triage maximizes lives saved.','original'),
('127.757.d.9.K',4,'The goal of triage during a mass casualty incident is to:','["treat nobody", "treat friends first", "treat the loudest first", "do the greatest good for the greatest number"]'::jsonb,3,'Prioritize by urgency and survivability.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
